def count_aliens(N: int, M: int, H: list[int]) -> int:
    remaining_disinfectant = M
    aliens_disinfected = 0

    for hands in H:
        if remaining_disinfectant >= hands:
            remaining_disinfectant -= hands
            aliens_disinfected += 1
        else:
            break

    return aliens_disinfected
